// Demonstrate cache-friendly (row-major) vs cache-unfriendly (column-major) access
const SIZE = 1000;
const matrix = Array.from({ length: SIZE }, () => new Int32Array(SIZE));

// Fill matrix
for (let r = 0; r < SIZE; r++)
  for (let c = 0; c < SIZE; c++)
    matrix[r][c] = r * SIZE + c;

// CACHE-FRIENDLY: row-major (sequential memory)
const t1 = performance.now();
let sum1 = 0;
for (let r = 0; r < SIZE; r++)
  for (let c = 0; c < SIZE; c++)
    sum1 += matrix[r][c];         // adjacent in memory
console.log('Row-major ms:', performance.now() - t1);

// CACHE-UNFRIENDLY: column-major (strided memory)
const t2 = performance.now();
let sum2 = 0;
for (let c = 0; c < SIZE; c++)
  for (let r = 0; r < SIZE; r++)
    sum2 += matrix[r][c];         // jumps 1000 elements each step
console.log('Col-major ms:', performance.now() - t2);
// Column-major is typically 2-5x slower due to cache misses

